mapper.select:
SELECT p.* FROM biz_party p
p.deleted = 0
AND (p.party_type = #{q.partyType} OR p.roles LIKE CONCAT('%', #{q.role}, '%'))
AND p.party_type = #{q.partyType}
AND p.status = #{q.status}
AND p.category_id = #{q.categoryId}
AND (p.party_code LIKE CONCAT('%', #{q.keyword}, '%') OR p.party_name LIKE CONCAT('%', #{q.keyword}, '%') OR p.short_name LIKE CONCAT('%', #{q.keyword}, '%') OR p.mnemonic_code LIKE CONCAT('%', #{q.keyword}, '%') OR p.phone LIKE CONCAT('%', #{q.keyword}, '%') OR p.remark LIKE CONCAT('%', #{q.keyword}, '%'))
AND p.settlement_type = #{q.settleType}
AND p.party_level LIKE CONCAT('%', #{q.gradeName}, '%')
AND p.default_handler_name LIKE CONCAT('%', #{q.handler}, '%')
AND p.promoter_name LIKE CONCAT('%', #{q.promoter}, '%')
AND p.warehouse_name LIKE CONCAT('%', #{q.warehouse}, '%')
AND (p.region LIKE CONCAT('%', #{q.region}, '%') OR EXISTS (SELECT 1 FROM biz_party_contact pc WHERE pc.party_id = p.id AND pc.deleted = 0 AND pc.region LIKE CONCAT('%', #{q.region}, '%')))
AND p.customer_source LIKE CONCAT('%', #{q.customerSource}, '%')
AND (p.address LIKE CONCAT('%', #{q.address}, '%') OR EXISTS (SELECT 1 FROM biz_party_contact pc2 WHERE pc2.party_id = p.id AND pc2.deleted = 0 AND pc2.detail_address LIKE CONCAT('%', #{q.address}, '%')))
AND p.buyer_account IS NOT NULL AND p.buyer_account <> ''
AND p.last_trade_time IS NULL
AND p.create_time >= #{q.createTimeStart}
AND p.create_time <= #{q.createTimeEnd}
AND p.last_trade_time >= #{q.lastTradeStart}
AND p.last_trade_time <= #{q.lastTradeEnd}
ORDER BY p.party_code DESC ORDER BY p.party_code ASC ORDER BY p.party_name DESC ORDER BY p.party_name ASC ORDER BY p.create_time DESC ORDER BY p.create_time ASC ORDER BY p.party_code ASC

SELECT p.*
FROM biz_party p

    p.deleted = 0

        AND p.party_type = #{q.partyType}

    AND ((p.member_card_no IS NOT NULL AND p.member_card_no <> '')
         OR (p.member_name IS NOT NULL AND p.member_name <> ''))

        AND p.category_id = #{q.categoryId}


        AND (p.party_code LIKE CONCAT('%', #{q.partyKeyword}, '%')
           OR p.party_name LIKE CONCAT('%', #{q.partyKeyword}, '%'))


        AND (p.member_name LIKE CONCAT('%', #{q.memberKeyword}, '%')
           OR p.member_card_no LIKE CONCAT('%', #{q.memberKeyword}, '%')
           OR p.party_name LIKE CONCAT('%', #{q.memberKeyword}, '%'))


        AND (p.phone LIKE CONCAT('%', #{q.phone}, '%')
           OR EXISTS (SELECT 1 FROM biz_party_contact pc
                       WHERE pc.party_id = p.id AND pc.deleted = 0
                         AND (pc.mobile LIKE CONCAT('%', #{q.phone}, '%')
                              OR pc.phone LIKE CONCAT('%', #{q.phone}, '%'))))


        AND p.id = #{q.customerId}


        AND p.default_handler_name LIKE CONCAT('%', #{q.handler}, '%')


        AND p.member_level = #{q.memberLevel}


        AND p.member_card_status = #{q.memberCardStatus}


        AND p.birthday = #{q.birthday}


        AND p.birthday IS NOT NULL
        AND DATE_PART('year', AGE(CURRENT_DATE, p.birthday)) >= #{q.ageMin}


        AND p.birthday IS NOT NULL
        AND DATE_PART('year', AGE(CURRENT_DATE, p.birthday)) <= #{q.ageMax}


        AND p.points >= #{q.pointsMin}


        AND p.points <= #{q.pointsMax}


        AND p.last_trade_time >= #{q.lastTradeStart}


        AND p.last_trade_time <= #{q.lastTradeEnd}


ORDER BY p.member_issue_time DESC NULLS LAST, p.id DESC

SELECT c.id, c.party_id, c.contact_id, COALESCE(ct.contact_name, c.contact_name) AS contact_name, COALESCE(ct.gender, c.gender) AS gender, c.position, COALESCE(ct.mobile, c.mobile) AS mobile, COALESCE(ct.phone, c.phone) AS phone, c.detail_address, c.delivery_method, c.delivery_route, c.logistics_company, COALESCE(ct.contact_name, c.contact_name) AS outlet_name, c.is_primary, c.status, c.create_time, p.party_name AS partner_name, p.party_code AS partner_code, p.region AS party_region, p.default_handler_name AS handler_name FROM biz_party_contact c INNER JOIN biz_party p ON c.party_id = p.id AND p.deleted = 0 LEFT JOIN biz_contact ct ON ct.id = c.contact_id AND ct.deleted = 0
c.deleted = 0
AND p.party_type = #{q.partyType}
AND c.party_id = #{q.customerId}
AND (COALESCE(ct.contact_name, c.contact_name) LIKE CONCAT('%', #{q.keyword}, '%') OR c.linkman LIKE CONCAT('%', #{q.keyword}, '%') OR COALESCE(ct.mobile, c.mobile) LIKE CONCAT('%', #{q.keyword}, '%') OR COALESCE(ct.phone, c.phone) LIKE CONCAT('%', #{q.keyword}, '%'))
AND p.default_handler_name LIKE CONCAT('%', #{q.handler}, '%')
AND c.detail_address LIKE CONCAT('%', #{q.address}, '%')
AND c.delivery_method = #{q.deliveryMethod}
AND (c.region LIKE CONCAT('%', #{q.region}, '%') OR p.region LIKE CONCAT('%', #{q.region}, '%'))
ORDER BY c.is_primary DESC, c.id DESC

SELECT p.*, c.category_name
FROM biz_party p
LEFT JOIN biz_party_category c ON p.category_id = c.id AND c.deleted = 0

    p.deleted = 0

        AND p.party_type = #{ew.partyType}


        AND p.status = #{ew.status}


        AND p.category_id = #{ew.categoryId}


        AND (p.party_name LIKE CONCAT('%', #{ew.keyword}, '%')
           OR p.party_code LIKE CONCAT('%', #{ew.keyword}, '%')
           OR p.phone LIKE CONCAT('%', #{ew.keyword}, '%'))


        AND p.settlement_type = #{ew.settleType}


        AND p.create_time >= #{ew.createTimeStart}


        AND p.create_time <= #{ew.createTimeEnd}


ORDER BY p.create_time DESC

SELECT p.*
FROM biz_party p

    p.deleted = 0

        AND p.party_type = #{ew.partyType}


        AND p.status = #{ew.status}


ORDER BY p.create_time DESC
LIMIT #{ew.pageSize}
